def find_bin(name: str) -> str | None:
    hit = shutil.which(name)
    if hit:
        return hit
    for d in BIN_DIRS[PLATFORM]:
        base = Path(d).expanduser()
        if not base.is_dir():
            continue
        for suf in EXE:
            f = base / f"{name}{suf}"
            if f.is_file():
                return str(f)
    return None


