        for line in (s.get("body") or "").splitlines():
            if line.strip():
                doc.add_paragraph(line.strip())
        for b in s.get("bullets") or []:
            doc.add_paragraph(b, style="List Bullet")
        if s.get("table"):
            cols = s["table"]["columns"]
            rows = s["table"]["rows"]
